<h2>Calculate production capacity</h2><p class="lead">Estimate gross theoretical output and expected good output over a selected operating period.</p>
<div class="form-grid"><div class="field"><label for="machines">Machines / parallel resources</label><input id="machines" type="number" min="1" step="1" value="4"></div><div class="field"><label for="hours">Hours per shift</label><input id="hours" type="number" min="0" step="any" value="8"></div><div class="field"><label for="shifts">Shifts per day</label><input id="shifts" type="number" min="0" step="any" value="2"></div><div class="field"><label for="days">Operating days in period</label><input id="days" type="number" min="0" step="any" value="22"></div><div class="field"><label for="rate">Rated output per machine-hour</label><input id="rate" type="number" min="0" step="any" value="50"></div><div class="field"><label for="eff">Expected run/efficiency factor (%)</label><input id="eff" type="number" min="0" max="100" step="any" value="85"></div><div class="field"><label for="yield">Good yield (%)</label><input id="yield" type="number" min="0" max="100" step="any" value="97"></div></div>
<div class="result-box"><div class="result-grid"><div class="metric"><span>Scheduled resource-hours</span><strong id="rh">—</strong></div><div class="metric"><span>Rated gross capacity</span><strong id="gross">—</strong></div><div class="metric"><span>Adjusted gross output</span><strong id="adjusted">—</strong></div><div class="metric"><span>Expected good output</span><strong id="good">—</strong></div></div></div>
<script>
(()=>{const $=id=>document.getElementById(id);function go(){const m=+$('machines').value,h=+$('hours').value,s=+$('shifts').value,d=+$('days').value,r=+$('rate').value,e=+$('eff').value/100,y=+$('yield').value/100;if(!(m>0&&h>=0&&s>=0&&d>=0&&r>=0&&e>=0&&e<=1&&y>=0&&y<=1)){['rh','gross','adjusted','good'].forEach(id=>$(id).textContent='—');return}const rh=m*h*s*d,g=rh*r,a=g*e,good=a*y;$('rh').textContent=rh.toLocaleString(undefined,{maximumFractionDigits:2})+' h';$('gross').textContent=g.toLocaleString(undefined,{maximumFractionDigits:0});$('adjusted').textContent=a.toLocaleString(undefined,{maximumFractionDigits:0});$('good').textContent=good.toLocaleString(undefined,{maximumFractionDigits:0})}['machines','hours','shifts','days','rate','eff','yield'].forEach(id=>$(id).addEventListener('input',go));go()})();
</script>
